-- 013 · 全类目商品目录（500 个商品）
--
-- **这个文件是生成的，别手改。** 配方在 deploy/scripts/gen_catalog.py，
-- 改配方重跑：python deploy/scripts/gen_catalog.py
--
-- 为什么要 500 个：12 个商品的店铺，导购 Agent 的筛选、放宽、追问
-- 三条分支全都触发不到（怎么筛都只剩那几件），覆盖度矩阵也只有
-- 一个类目。跨类目之后这些链路才有东西可跑。
--
-- ---------------------------------------------------------------- 属性随类目走
--
-- 每个类目有自己的属性 schema：食品是配料/净含量/保质期，图书是
-- 作者/出版社/页数，只有服饰鞋靴才有颜色×尺码，也只有它们有尺码表。
--
-- **给一包薯片写「尺码 M」不只是难看**：运营 Agent 的提示词是从属性表
-- 拼的，会生成「薯片，尺码 M」这种画面；导购按颜色/尺码筛选，会把零食
-- 筛进「想要件外套」的结果里；知识运维的依据核查会拿这些属性当事实。
--
-- ---------------------------------------------------------------- 没有配图
--
-- 仓库里只有 9001–9012 那 12 张实拍。把它们循环贴到 500 个商品上，
-- 就会出现「巧克力饼干」配一张针织衫照片——那比没有图糟得多。
-- main_image 留空，页面按类目渲染带类目名的占位块。
--
-- 商品 570 · SKU 1700 · 属性 2480 · 尺码表 50 · 类目 127
--
-- 执行：mysql -u root -p smartmall < deploy/sql/migrations/013_catalog_500.sql

